CREATE OR REPLACE FUNCTION ECAMS.PFMCHECK
(ACPTNO IN VARCHAR2,SERNO IN VARCHAR2)
RETURN VARCHAR2
IS
   VCNT1 INT := 0;
 --- 자신의 기준프로그램이 프로프레임형상항목인지 CHECK
BEGIN
    SELECT  COUNT(*)
      INTO  VCNT1
      FROM  CMM0036 D,CMR1010 C,CMM0036 B,CMR1010 A
     WHERE  A.CR_ACPTNO=ACPTNO
       AND  A.CR_SERNO=SERNO
       AND  (SUBSTR(A.CR_ACPTNO,5,2)='03' OR
             (SUBSTR(A.CR_ACPTNO,5,2)='04' AND
              SUBSTR(A.CR_ACPTNO,5,2)<>'03'))
       AND  A.CR_SYSCD=B.CM_SYSCD
       AND  A.CR_RSRCCD=B.CM_RSRCCD
       AND  SUBSTR(B.CM_INFO,26,1)='1'
       AND  A.CR_ACPTNO=C.CR_ACPTNO
       AND  A.CR_BASEITEM=C.CR_ITEMID
       AND  C.CR_SYSCD=D.CM_SYSCD
       AND  C.CR_RSRCCD=D.CM_RSRCCD
       AND  SUBSTR(D.CM_INFO,27,1)='1';

     IF VCNT1 > 0 THEN
        RETURN 'Y';
     ELSE RETURN 'N';
     END IF;
end;